// Generates src/palettes.ts from guide/palettes.json (the machine-readable copy of Appendix A / §7.3).
// The guide/ folder is not part of the repository; the generated file is committed.
import { readFileSync, writeFileSync } from "node:fs";

const src = process.argv[2] ?? "guide/palettes.json";
const data = JSON.parse(readFileSync(src, "utf8"));
const keys = data.roles ? Object.keys(data.roles) : Object.keys(data.palettes.prism.dark);

const lines = [];
lines.push("// GENERATED by scripts/gen-palettes.mjs from guide/palettes.json. Do not edit by hand.");
lines.push("");
lines.push(`export type PaletteKey = ${keys.map((k) => JSON.stringify(k)).join(" | ")};`);
lines.push('export type StyleName = "prism" | "circuit" | "rail";');
lines.push('export type Appearance = "dark" | "light";');
lines.push('export type ThinkLevel = "off" | "minimal" | "low" | "medium" | "high" | "xhigh" | "max";');
lines.push("export type Palette = Record<PaletteKey, string>;");
lines.push("");
lines.push("export const PALETTES: Record<StyleName, Record<Appearance, Palette>> = " + JSON.stringify(data.palettes, null, 2) + ";");
lines.push("");
lines.push("/** Thinking-level pill fills (§7.3), already mixed from dim → s3 → err. */");
lines.push("export const THINKING_RAMP: Record<StyleName, Record<Appearance, Record<ThinkLevel, string>>> = " + JSON.stringify(data.thinkingRamp, null, 2) + ";");
lines.push("");
writeFileSync("src/palettes.ts", lines.join("\n"));
console.log("wrote src/palettes.ts");
